import {COUNTRIES} from './countries.mjs';
import {mountDashboard,icon,escapeHTML} from './dashboard.mjs';
import {createKycService,validateKycDetails} from './kyc-service.mjs';
const countries=COUNTRIES.map(c=>c.code);
const names=new Intl.DisplayNames(['en'],{type:'region'});
export function kycWelcomeHTML(){return '<div class="kyc-page"><h1>Identity Verification</h1><section class="kyc-card"><div class="kyc-emblem">'+icon('shield')+'</div><h2>Verify Your Identity</h2><p class="kyc-intro">Submit your details and photos for a manual identity review.</p><ul class="kyc-requirements"><li>'+icon('user')+'<div><strong>Government-issued ID</strong><span>Passport, national ID, or driver’s license</span></div></li><li>'+icon('shield')+'<div><strong>Selfie photo</strong><span>A clear photo of your face, without filters</span></div></li><li>'+icon('volume')+'<div><strong>Save your progress</strong><span>Return to finish your draft at any time</span></div></li></ul><div class="kyc-privacy">'+icon('shield')+'<p>Your photos are stored privately in Aurexmarkets’ Supabase project for manual review. Submitting does not automatically verify your identity or enable trading.</p></div><p id="kyc-message" class="kyc-message" role="status"></p><button id="kyc-start" class="deposit-continue">Start Verification '+icon('arrow')+'</button><p class="kyc-note">JPG or PNG · Up to 6 MB per photo · Ages 18+</p></section></div>';}
export function mountKyc(root,options={}){
 mountDashboard(root,{...options,view:'kyc',mainHTML:kycWelcomeHTML()});const main=root.querySelector('main');let service,row,step=0,busy=false,stream;const alive=()=>main.isConnected;
 function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;}
 function message(text,error=false){const el=main.querySelector('#kyc-message');if(el){el.textContent=text;el.classList.toggle('error',error);el.setAttribute('role',error?'alert':'status');}}
 async function action(fn){if(busy)return;busy=true;main.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);try{await fn();}catch(error){message(error.message||'Unable to save. Please try again.',true);}finally{busy=false;if(alive())main.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);}}
 function frame(content){stopCamera();main.innerHTML='<div class="kyc-page"><h1>Identity Verification</h1><section class="kyc-card kyc-flow"><ol class="kyc-steps">'+['Details','Photos','Review'].map((name,i)=>'<li class="'+(step===i+1?'active':'')+'">'+(i+1)+'. '+name+'</li>').join('')+'</ol>'+content+'<p id="kyc-message" class="kyc-message" role="status"></p></section></div>';}
 function details(){step=1;frame('<h2>Your details</h2><p class="kyc-intro">Use the details shown on your identity document.</p><form id="kyc-details" class="account-form"><label class="field">Full legal name<input name="full_name" autocomplete="name" required minlength="2" maxlength="160"></label><label class="field">Date of birth<input name="date_of_birth" type="date" autocomplete="bday" required></label><label class="field">Country of residence<select name="country" required><option value="">Choose a country</option>'+countries.sort((a,b)=>names.of(a).localeCompare(names.of(b))).map(c=>'<option value="'+c+'">'+names.of(c)+'</option>').join('')+'</select></label><label class="field">Document type<select name="document_type"><option value="passport">Passport</option><option value="national_id">National ID</option><option value="drivers_license">Driver’s license</option></select></label><button class="deposit-continue" type="submit">Save &amp; Continue '+icon('arrow')+'</button></form>');const form=main.querySelector('form');for(const key of ['full_name','date_of_birth','country','document_type'])if(row?.[key])form.elements[key].value=row[key];form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));action(async()=>{validateKycDetails(values);if(!service)throw Error('Sign in to save your verification details.');row=await service.save(values);if(alive())photos();});};}
 function photos(){step=2;const slots=[['document_front',row.document_type==='passport'?'Passport photo page':'ID front'],...(row.document_type!=='passport'?[['document_back','ID back']]:[]),['selfie','Selfie photo']];frame('<h2>Upload your photos</h2><p class="kyc-intro">Make sure all details are readable. Your face and document edges should be fully visible.</p>'+slots.map(([slot,label])=>'<div class="kyc-upload"><label class="field">'+label+'<input data-upload="'+slot+'" type="file" accept="image/jpeg,image/png" '+(slot==='selfie'?'capture="user"':'')+'></label><span class="kyc-file-status">'+(row[slot+'_path']?'✓ Photo saved privately':'No photo uploaded')+'</span></div>').join('')+'<button id="kyc-camera" type="button" class="secondary-button">Use camera for selfie</button><div id="kyc-camera-panel" hidden><video id="kyc-video" autoplay playsinline muted></video><button id="kyc-capture" class="secondary-button" type="button">Capture selfie</button><button id="kyc-stop-camera" class="secondary-button" type="button">Close camera</button></div><p class="kyc-note">JPG or PNG, up to 6 MB. This is a photo submission, not an automated liveness check.</p><div class="kyc-actions"><button id="kyc-back" class="secondary-button">Back</button><button id="kyc-review" class="deposit-continue">Review Submission</button></div>');main.querySelectorAll('[data-upload]').forEach(input=>input.onchange=()=>{const file=input.files[0];if(!file)return;action(async()=>{row=await service.upload(input.dataset.upload,file);if(alive()){photos();message('Photo saved privately.');}});});main.querySelector('#kyc-back').onclick=details;main.querySelector('#kyc-review').onclick=()=>{if(slots.some(([slot])=>!row[slot+'_path']))return message('Upload all required photos before continuing.',true);review();};main.querySelector('#kyc-camera').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera unavailable. Upload a selfie photo instead.');stopCamera();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});if(!alive()){stopCamera();return;}main.querySelector('#kyc-video').srcObject=stream;main.querySelector('#kyc-camera-panel').hidden=false;}catch{message('Camera unavailable or permission denied. You can upload a selfie photo instead.',true);}};main.querySelector('#kyc-stop-camera').onclick=()=>{stopCamera();main.querySelector('#kyc-camera-panel').hidden=true;};main.querySelector('#kyc-capture').onclick=()=>action(async()=>{const video=main.querySelector('#kyc-video');if(!video.videoWidth)throw Error('Wait for the camera image, then try again.');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));stopCamera();if(!blob)throw Error('Could not capture photo. Please try again.');row=await service.upload('selfie',new File([blob],'selfie.jpg',{type:'image/jpeg'}));if(alive())photos();});}
 function review(){step=3;frame('<h2>Review your submission</h2><dl class="kyc-summary"><dt>Full legal name</dt><dd>'+escapeHTML(row.full_name)+'</dd><dt>Date of birth</dt><dd>'+escapeHTML(row.date_of_birth)+'</dd><dt>Country</dt><dd>'+escapeHTML(names.of(row.country))+'</dd><dt>Document</dt><dd>'+escapeHTML({passport:'Passport',national_id:'National ID',drivers_license:'Driver’s license'}[row.document_type])+'</dd><dt>Required photos</dt><dd>Uploaded privately</dd></dl><form id="kyc-submit-form"><label class="kyc-consent"><input type="checkbox" id="kyc-consent" required><span>I confirm these details and photos belong to me and consent to their storage and manual review for identity verification.</span></label><p class="kyc-note">Your documents are not public. Review does not automatically enable trading or money transfers.</p><div class="kyc-actions"><button type="button" id="kyc-back" class="secondary-button">Back</button><button type="submit" class="deposit-continue">Submit for Review</button></div></form><button id="kyc-delete" class="kyc-delete" type="button">Delete draft and uploaded photos</button>');main.querySelector('#kyc-back').onclick=photos;main.querySelector('#kyc-submit-form').onsubmit=e=>{e.preventDefault();const consent=main.querySelector('#kyc-consent').checked;action(async()=>{row=await service.submit(consent);if(alive())status();});};main.querySelector('#kyc-delete').onclick=()=>action(async()=>{await service.removeDraft();row=null;if(alive())welcome();});}
 function status(){step=0;const verified=row.status==='verified';frame('<div class="kyc-emblem">'+icon('shield')+'</div><h2>'+(verified?'Identity verified':'Submitted for review')+'</h2><p class="kyc-intro">'+(verified?'Your identity submission has been marked verified by a reviewer.':'Your details and photos were saved successfully. Your verification is pending manual review.')+'</p><span class="kyc-status">'+(verified?'Verified':'Pending review')+'</span><p class="kyc-note">Submitted '+escapeHTML(new Date(row.consent_at||row.created_at).toLocaleDateString())+'</p><button class="secondary-button" id="kyc-refresh">Refresh Status</button><a class="deposit-continue" href="#/dashboard">Back to Dashboard</a>');main.querySelector('#kyc-refresh').onclick=()=>action(async()=>{row=await service.load();if(alive())row&&['pending','verified'].includes(row.status)?status():welcome();});}
 function welcome(){stopCamera();main.innerHTML=kycWelcomeHTML();const b=main.querySelector('#kyc-start');if(row){b.textContent=row.status==='rejected'?'Update Verification':'Continue Verification';if(row.status==='rejected')message(row.review_note||'Your submission needs changes. Please review and resubmit.',true);}b.onclick=details;}
 main.querySelector('#kyc-start').disabled=!options.preview;main.querySelector('#kyc-start').onclick=details;
 if(!options.preview)(async()=>{try{const accounts=await options.getAccounts();service=createKycService(accounts);row=await service.load();if(!alive())return;if(row&&['pending','verified'].includes(row.status))status();else welcome();}catch(error){if(alive()){message(error.message||'Unable to load verification. Please try again.',true);const button=main.querySelector('#kyc-start');button.disabled=false;button.textContent='Retry';button.onclick=()=>mountKyc(root,options);}}})();
 const observer=new MutationObserver(()=>{if(!alive()){stopCamera();observer.disconnect();}});observer.observe(root,{childList:true});window.addEventListener('pagehide',stopCamera,{once:true});
}
